<?php use AlbaTech\Core\View; ?>
<div class="welcome-row"><div><h2>Manage your articles</h2><p>Create and update the guides shown on your public website.</p></div><a class="btn btn-primary" href="/admin/guides/create"><i class="fa-solid fa-plus"></i> Write a guide</a></div>
<div class="panel"><div class="panel-head"><div><h3>Guides & resources</h3><p>Drafts stay private until published.</p></div><span class="muted-count"><?= count($guides ?? []) ?> total</span></div>
<div class="table-wrap"><table><thead><tr><th>Guide</th><th>Category</th><th>Status</th><th>Last updated</th><th>Actions</th></tr></thead><tbody>
<?php foreach (($guides ?? []) as $guide): ?><tr><td><strong><?= View::escape($guide['title']) ?></strong><small class="guide-slug">/guides/<?= View::escape($guide['slug']) ?></small></td><td><?= View::escape($guide['category']) ?></td><td><span class="status-pill <?= $guide['status']==='published'?'status-live':'status-draft' ?>"><?= View::escape(ucfirst($guide['status'])) ?></span></td><td><?= View::escape(date('j M Y',strtotime($guide['updated_at']))) ?></td><td><div class="actions-cell"><a class="btn btn-light" href="/admin/guides/<?= (int)$guide['id'] ?>/edit"><i class="fa-solid fa-pen"></i> Edit</a><form method="post" action="/admin/guides/<?= (int)$guide['id'] ?>/delete" data-confirm="Delete this guide permanently?"><input type="hidden" name="_csrf" value="<?= View::escape($csrf) ?>"><button class="btn btn-light" type="submit" aria-label="Delete guide"><i class="fa-solid fa-trash"></i></button></form><?php if ($guide['status']==='published'): ?><a class="btn btn-light" target="_blank" rel="noopener" href="/guides/<?= rawurlencode($guide['slug']) ?>"><i class="fa-solid fa-arrow-up-right-from-square"></i> View</a><?php endif; ?></div></td></tr><?php endforeach; ?>
<?php if (empty($guides)): ?><tr><td colspan="5" class="empty-state">No database-managed guides yet. Write your first guide to get started.</td></tr><?php endif; ?>
</tbody></table></div></div>
